it.effect.each([MODEL, null])("uses native MSP metadata without inventing model $0 or PM turns", nativeModel =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem;
    const cwd = yield* fs.makeTempDirectoryScoped({ prefix: "muse-legacy-metadata-" });
    const fake = yield* makeFakeMuse();
    fake.host.initializeResult.schema = { version: 1, fingerprint: `sha256:${"a".repeat(64)}` };
    const policy = ProviderAdapter.ProviderAdapterV2RuntimePolicy.make({ cwd, runtimeMode: "approval-required", interactionMode: "default" });
    const adapter = yield* makeMuseAdapterV2({ instanceId: INSTANCE_ID, settings: museSettings,
      environment: { HOME: cwd }, createHost: async () => fake.host });
    const providerSessionId = ProviderSessionId.make("muse-legacy-operation");
    const runtime = yield* adapter.openSession({ threadId: THREAD_ID, providerSessionId,
      modelSelection: modelSelection(), runtimePolicy: policy, initialNativeThreadId: "saved-native-session" });
    const evidence = readMuseSessionEvidence(runtime)!;
    assert.equal((yield* evidence.probe).protocol, `muse-msp:1:sha256:${"a".repeat(64)}`);
    assert.equal(fake.calls.length, 0);
    const metadata = { session: { sessionId: "saved-native-session", workspaceRoot: cwd,
      status: "notLoaded", activeTurnId: null, modelId: nativeModel },
      lastTurn: { turnId: "native-completed-turn", terminal: "completed" } };
    fake.queueResponse("session/read", metadata);
    const ensure = { threadId: THREAD_ID, providerSessionId, modelSelection: modelSelection(), runtimePolicy: policy };
    const snapshot = yield* evidence.readLegacy({ nativeSessionId: "saved-native-session", turnId: "native-completed-turn", ensure });
    assert.equal(snapshot.providerThread.nativeThreadRef?.nativeId, "saved-native-session");
    assert.deepEqual(snapshot.providerTurns, []);
    assert.deepEqual(snapshot.nativeHistory, { nativeSessionId: "saved-native-session",
      completedTurnRefs: [{ driver: MUSE_PROVIDER, nativeId: "native-completed-turn", strength: "strong" }] });
    assert.equal(snapshot.providerThread.nativeMetadata?.modelSelection?.model, nativeModel ?? undefined);
    assert.equal(fake.calls[0]?.method, "session/read");
    assert.isFalse(fake.calls.some(call => call.method === "turn/start" || call.method === "session/start"));
    const resumed = fake.calls.filter(call => call.method === "session/resume").length;
    for (const lastTurn of [null, { turnId: "native-completed-turn", terminal: "failed" },
      { turnId: "native-completed-turn", terminal: "cancelled" }, { turnId: "", terminal: "completed" }]) {
      fake.queueResponse("session/read", { ...metadata, lastTurn });
      assert.equal((yield* evidence.readLegacy({ nativeSessionId: "saved-native-session", ensure }).pipe(Effect.result))._tag, "Failure");
    }
    fake.queueResponse("session/read", { ...metadata, session: { ...metadata.session, workspaceRoot: "/foreign-workspace" } });
    assert.equal((yield* evidence.readLegacy({ nativeSessionId: "saved-native-session", ensure }).pipe(Effect.result))._tag, "Failure");
    assert.equal(fake.calls.filter(call => call.method === "session/resume").length, resumed);
    const reads = fake.calls.filter(call => call.method === "session/read").length;
    assert.equal((yield* evidence.readLegacy({ nativeSessionId: "foreign-native-session", ensure }).pipe(Effect.result))._tag, "Failure");
    assert.equal(fake.calls.filter(call => call.method === "session/read").length, reads);
  }).pipe(Effect.scoped, Effect.provide(testLayer)),
);

